INSERT INTO productos (id, codigo, nombre, descripcion, categoria_id, proveedor_id, temporada_id, tipo_producto_id, categoria_nombre, proveedor_nombre, genero, material_principal, materiales_detalle, peso_gramos, precio_compra, margen_ganancia, precio_venta, precio_oferta, stock_actual, stock_minimo, stock_maximo, ubicacion_fisica, tiene_medidas, medidas, permite_personalizacion, imagen_principal, es_nuevo, es_destacado, activo, creado_por, actualizado_por, fecha_creacion, fecha_actualizacion, precio_personalizacion, ubicaciones_entrega) VALUES (1, 'EPR-DIAPADRE-0001', 'Esclava personalizada Día del Padre', 'Este Día del Padre regálale algo que lleve siempre con él. Esclavas personalizadas con nombre, frase o fecha. Llaveros personalizados con fotografías, mensajes o dibujos animados. Cadenitas con dijes o placas con grabado láser. Un Detalle Único para Papá. Envíanos un mensaje por WhatsApp al 771 332 1421 para cotizar precios o agendar tu pedido con anticipación. Entregas en Huejutla Hgo. Envíos a Atlapexco, San Felipe Orizatlán, Tehuetlán, Tlanchinol, Huautla, Xochiatipan, Santa Cruz y municipios alrededores.', 14, 31, NULL, 12, 'esclavas', 'Proveedor 31', 'caballero', 'Plata', NULL, '6.200', 0, 0, '900.55', NULL, 47, 5, 999, NULL, false, NULL, true, 'https://res.cloudinary.com/dltvkwwq4/image/upload/v1782715757/Producto_1_esclavas_gilfyj.jpg', true, false, true, NULL, NULL, '2026-06-29T02:25:32.370Z', '2026-07-29T03:24:59.620Z', '0.00', '["Huejutla","San Felipe","Jaltocan","Tampico","Tehuetlan"]');
INSERT INTO productos (id, codigo, nombre, descripcion, categoria_id, proveedor_id, temporada_id, tipo_producto_id, categoria_nombre, proveedor_nombre, genero, material_principal, materiales_detalle, peso_gramos, precio_compra, margen_ganancia, precio_venta, precio_oferta, stock_actual, stock_minimo, stock_maximo, ubicacion_fisica, tiene_medidas, medidas, permite_personalizacion, imagen_principal, es_nuevo, es_destacado, activo, creado_por, actualizado_por, fecha_creacion, fecha_actualizacion, precio_personalizacion, ubicaciones_entrega) VALUES (2, 'APR-DIAMADRE-0001', 'Aretes corazón doble plata', 'Porque mamá se merece un Regalo único y Especial como ella. Sorprende a mamá, aquí te dejamos algunas ideas de obsequios para este 10 de Mayo. Relicarios personalizados, Pulseras, Anillos, Cadenitas, Rosarios, aretes y muchas cosas más. Joyería y Bisutería, en distintos materiales: plata ley .925, acero inoxidable, chapa de oro, laminado de oro. Contáctanos al WhatsApp 771 332 1421. Entregas en Huejutla de Reyes Hgo. Envíos a Atlapexco, San Felipe, Tlanchinol, Santa Cruz, Xochiatipan, Tehuetlán, Jaltocan y municipios alrededores.', 4, 31, NULL, 1, 'Aretes', 'Proveedor 31', 'dama', 'Plata', NULL, '2.500', 0, 0, '219.42', NULL, 46, 5, 999, NULL, false, NULL, false, 'https://res.cloudinary.com/dltvkwwq4/image/upload/v1782715755/Producto_2_aretes_fewhbb.jpg', true, false, true, NULL, NULL, '2026-06-29T13:06:37.950Z', '2026-07-29T03:24:59.620Z', '0.00', '["Huejutla","San Felipe","Jaltocan","Tampico","Tehuetlan"]');
INSERT INTO productos (id, codigo, nombre, descripcion, categoria_id, proveedor_id, temporada_id, tipo_producto_id, categoria_nombre, proveedor_nombre, genero, material_principal, materiales_detalle, peso_gramos, precio_compra, margen_ganancia, precio_venta, precio_oferta, stock_actual, stock_minimo, stock_maximo, ubicacion_fisica, tiene_medidas, medidas, permite_personalizacion, imagen_principal, es_nuevo, es_destacado, activo, creado_por, actualizado_por, fecha_creacion, fecha_actualizacion, precio_personalizacion, ubicaciones_entrega) VALUES (3, 'PPR-DIANINO-0001', 'Pulsera personalizada Día del Niño', 'Pulseras para obsequiar este 30 de Abril. Recuerda que ya estamos agendando pedidos para este Día del Niño. Se pueden personalizar con el nombre de los niños y la temática que desees, para niños y niñas: reconocimientos, princesas, Avengers y superhéroes, Bluey, Mario Bros, o alguna otra temática que tengas en mente. Contáctanos al WhatsApp 771 332 1421. Entregas en Huejutla de Reyes Hgo. Envíos a San Felipe, Tehuetlán, Tlanchinol, Atlapexco, Santa Cruz, Jaltocan, Xochiatipan y alrededores. Agenda tu pedido con anticipación. Pulseritas disponibles para adultos y niños.', 3, 31, NULL, 12, 'Pulseras', 'Proveedor 31', 'unisex', 'Acero/cuentas plásticas (bisutería)', NULL, '1.500', 0, 0, '55.76', NULL, 44, 5, 999, NULL, false, NULL, true, 'https://res.cloudinary.com/dltvkwwq4/image/upload/v1782715751/Producto_3_pulseras_jepn4x.jpg', true, false, true, NULL, NULL, '2026-06-29T13:10:10.769Z', '2026-07-29T03:24:59.620Z', '0.00', '["Huejutla","San Felipe","Jaltocan","Tampico","Tehuetlan"]');
INSERT INTO productos (id, codigo, nombre, descripcion, categoria_id, proveedor_id, temporada_id, tipo_producto_id, categoria_nombre, proveedor_nombre, genero, material_principal, materiales_detalle, peso_gramos, precio_compra, margen_ganancia, precio_venta, precio_oferta, stock_actual, stock_minimo, stock_maximo, ubicacion_fisica, tiene_medidas, medidas, permite_personalizacion, imagen_principal, es_nuevo, es_destacado, activo, creado_por, actualizado_por, fecha_creacion, fecha_actualizacion, precio_personalizacion, ubicaciones_entrega) VALUES (4, 'EPR-LAMORO-0001', 'Esclava laminado de oro figaro', 'Esclava de laminado de oro con eslabón estilo figaro y placa lisa, ideal para caballero. Un diseño clásico, resistente y de acabado brillante que combina elegancia con durabilidad. Pregunta por nuestros otros modelos disponibles. Contáctanos al WhatsApp 771 332 1421. Entregas en Huejutla de Reyes Hgo. Envíos a municipios alrededores.', 14, 31, NULL, 1, 'esclavas', 'Proveedor 31', 'caballero', 'Laminado de oro', NULL, '12.500', 0, 0, '849.40', NULL, 48, 5, 999, NULL, false, NULL, false, 'https://res.cloudinary.com/dltvkwwq4/image/upload/v1782717198/Producto_4_esclavas_n7nlbz.jpg', true, false, true, NULL, NULL, '2026-06-29T13:16:49.814Z', '2026-07-29T03:24:59.620Z', '0.00', '["Huejutla","San Felipe","Jaltocan","Tampico","Tehuetlan"]');
