INSERT INTO configuracion (id, clave, valor, tipo_dato, descripcion, categoria, es_sensible, actualizado_por, fecha_actualizacion) VALUES (22, 'sitio_mision_vision_valores', '{"mision":"Proporcionar joyas de alta calidad con diseños exclusivos que reflejen la elegancia y personalidad de nuestros clientes.","vision":"Ser la joyería de referencia en la región, reconocida por nuestra excelencia, innovación y compromiso con nuestros clientes.","valores":["Calidad: Comprometidos con la excelencia en cada pieza","Integridad: Transparencia total en nuestros procesos","Innovación: Diseños únicos y exclusivos","Servicio: Atención excepcional a nuestros clientes"]}', 'json', 'Misión, visión y valores que se muestran en Sobre nosotros', 'contenido', false, 17, '2026-09-27T15:01:03.323Z');
