-- Catálogo público de la tienda para la prueba de esfuerzo aislada (#230).
-- Generado desde la base de producción el 25 oct 2026. Sin datos internos: precio de compra, margen,
-- ubicación física y usuarios en blanco; proveedores con nombres genéricos; sin reseñas ni clientes.
SET session_replication_role = replica;
SELECT setval('public.categorias_id_seq', (SELECT COALESCE(MAX(id), 1) FROM categorias));
SELECT setval('public.temporadas_id_seq', (SELECT COALESCE(MAX(id), 1) FROM temporadas));
SELECT setval('public.tipos_producto_id_seq', (SELECT COALESCE(MAX(id), 1) FROM tipos_producto));
SELECT setval('public.promociones_id_seq', (SELECT COALESCE(MAX(id), 1) FROM promociones));
SELECT setval('public.imagenes_producto_id_seq', (SELECT COALESCE(MAX(id), 1) FROM imagenes_producto));
SELECT setval('public.proveedores_id_seq', (SELECT COALESCE(MAX(id), 1) FROM proveedores));
SELECT setval('public.productos_id_seq', (SELECT COALESCE(MAX(id), 1) FROM productos));
SELECT setval('public.configuracion_id_seq', (SELECT COALESCE(MAX(id), 1) FROM configuracion));
SET session_replication_role = DEFAULT;
